mapper.insert:
INSERT INTO xxl_ai_session_msg (
	session_id, role, reasoning, content, status, add_time, update_time
) VALUES (
	 #{sessionId}, #{role}, #{reasoning}, #{content}, #{status}, NOW(), NOW()
 );

mapper.delete:
DELETE t FROM xxl_ai_session_msg AS t
JOIN xxl_ai_session AS c ON t.session_id = c.id
WHERE c.agent_id = #{agentId}

mapper.select:
SELECT 
FROM xxl_ai_session_msg AS t
WHERE t.session_id = #{sessionId}
ORDER BY t.id DESC
LIMIT #{offset}, #{pagesize}

SELECT 
FROM xxl_ai_session_msg AS t
WHERE t.session_id = #{sessionId} AND t.id  <  #{beforeId}
ORDER BY t.id DESC
LIMIT #{limit}

SELECT count(1)
FROM xxl_ai_session_msg AS t
WHERE t.session_id = #{sessionId}
